INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('ARTE', NULL, 'A orillas del Guadalquivir se levanta una torre que antiguamente se usaba para impedir la entrada de enemigos en Sevilla. ¿Cómo se llama la torre?', 'La Torre del Oro', 'Desde la Torre se extendía una cadena hasta la otra orilla del río, para así cortar el paso a los enemigos.', 'Desde la Torre se extendía una cadena hasta la otra orilla del río, para así cortar el paso a los enemigos.', 'LEIVA', 'LUIS', NULL, NULL, 'verificada', '_1LS', NOW(), 0);
