INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('TELEVISIÓN', NULL, 'La pikachurina es una proteína que tenemos en la retina del ojo que debe su nombre a un personaje de animación. ¿Cuál?', 'Pikachu', 'La pikachurina se encarga de trasladar de forma veloz la información de los ojos al cerebro, y por eso se llama como Pikachu, porque también era muy rápido. Y este simpático nombre se lo debemos a los investigadores de la Universidad de Osaka que la descubrieron en 2008. ', 'La pikachurina se encarga de trasladar de forma veloz la información de los ojos al cerebro, y por eso se llama como Pikachu, porque también era muy rápido. Y este simpático nombre se lo debemos a los investigadores de la Universidad de Osaka que la descubrieron en 2008. ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_1LS', NOW(), 0);
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CIENCIAS', NULL, '¿Qué ingrediente de los huevos a la flamenca usó Mendel para elaborar sus leyes de la genética?', 'Los guisantes', 'Ni huevos ni chorizos, Mendel se convirtió en el padre de la genética moderna experimentando con guisantes. A través de ellos, consiguió explicar cómo va a ser un individuo partiendo de los rasgos de sus padres y abuelos. ', 'Ni huevos ni chorizos, Mendel se convirtió en el padre de la genética moderna experimentando con guisantes. A través de ellos, consiguió explicar cómo va a ser un individuo partiendo de los rasgos de sus padres y abuelos. ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_3LS', NOW(), 0);
