INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('TRADICIONES', NULL, '¿Cuál es el único animal mitológico del horóscopo chino?', 'El dragón', 'Los doce animales del horóscopo chino son: la rata, el buey, el tigre, el conejo, la serpiente, el caballo, la cabra, el mono, el gallo, el perro, el cerdo y el dragón, y el único que no existe es el dragón ', 'Los doce animales del horóscopo chino son: la rata, el buey, el tigre, el conejo, la serpiente, el caballo, la cabra, el mono, el gallo, el perro, el cerdo y el dragón, y el único que no existe es el dragón ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_1LS', NOW(), 0);
