INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('GEOGRAFÍA', NULL, '¿Qué país de los países nórdicos está más al sur?', 'Dinamarca', 'Los países nórdicos son cinco: Dinamarca, Finlandia, Noruega, Suecia e Islandia. A estos, se les suma los tres territorios autónomos conectados a los estados: las Islas Feroe y Groenlandia a Dinamarca, las islas Åland, a Finlandia. ', 'Los países nórdicos son cinco: Dinamarca, Finlandia, Noruega, Suecia e Islandia. A estos, se les suma los tres territorios autónomos conectados a los estados: las Islas Feroe y Groenlandia a Dinamarca, las islas Åland, a Finlandia. ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_3LS', NOW(), 0);
