INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('NATURALEZA', NULL, 'Gila fue un monstruo de la comedia en España, ¿pero qué tipo de reptil es el monstruo de Gila que vive en América del Norte? ', 'Un lagarto', 'Es un lagarto venenoso que debe su nombre al río Gila, situado en el suroeste de los Estados Unidos. Puede llegar a medir hasta 60 centímetros, pero no temáis, porque sus movimientos son lentos y pesados, tendréis tiempo para escapar.', 'Es un lagarto venenoso que debe su nombre al río Gila, situado en el suroeste de los Estados Unidos. Puede llegar a medir hasta 60 centímetros, pero no temáis, porque sus movimientos son lentos y pesados, tendréis tiempo para escapar.', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_1LS', NOW(), 0);
