INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LENGUAJE', NULL, 'En los años 80, el diseñador Adolfo Domínguez popularizó un eslogan que decía "la arruga es..."', 'Bella', 'El diseñador gallego defendía el confort de los tejidos naturales y de la ropa holgada, aunque este mensaje se ha acabado usando aceptar el paso del tiempo con naturalidad y que la vejez también puede ser bella. ', 'El diseñador gallego defendía el confort de los tejidos naturales y de la ropa holgada, aunque este mensaje se ha acabado usando aceptar el paso del tiempo con naturalidad y que la vejez también puede ser bella. ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_3LS', NOW(), 0);
