INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LENGUAJE', NULL, '¿Qué significa la palabra "xoxo" con la que se despide un estadounidense por correo electrónico?', 'Abrazos y besos', '"Xoxo" significa "hugs and kisses", es decir, "abrazos y besos" y se usa como despedida informal entre amigos y familiares. Vamos, que nunca le envíes un "xoxo" a tu jefe. ', '"Xoxo" significa "hugs and kisses", es decir, "abrazos y besos" y se usa como despedida informal entre amigos y familiares. Vamos, que nunca le envíes un "xoxo" a tu jefe. ', 'LEIVA', NULL, NULL, NULL, 'para_verificar', '_1LS', NOW(), 0);
