INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('CULTURA POP', 'OESTE', '"La mano del muerto" es una jugada de póker apodada así en el lejano Oeste. Se compone de dos ochos y ¿qué otra pareja de cartas?', 'Dos ases', 'Recibía este nombre por Wild BIll Hickock, un famoso pistolero que cuando fue asesinado mientras jugaba al póker sostenía esas mismas cartas.', 'Recibía este nombre por Wild BIll Hickock, un famoso pistolero que cuando fue asesinado mientras jugaba al póker sostenía esas mismas cartas.', 'SARA', 'LEIVA', ' ', ' ', 'borrador', '_5LS', NOW(), 0);
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('LENGUAJE', 'OESTE', 'Los estadounidenses del siglo XIX se referían despectivamente a los nativos americanos como pieles…¿qué?', 'Pieles rojas', 'Ni pieles rojas ni indios. Indígenas o nativos. Que bastante tuvieron con que los echaran de sus tierras…', 'Ni pieles rojas ni indios. Indígenas o nativos. Que bastante tuvieron con que los echaran de sus tierras…', 'SARA', 'LEIVA', ' ', ' ', 'verificada', '_1LS', NOW(), 0);
INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('GASTRONOMÍA', NULL, '¿Qué dos salsas son la base para preparar una salsa rosa?', 'El kétchup y la mayonesa / Salsa de tomate y mayonesa', 'También se conoce como salsa cóctel porque es la típica salsita que lleva un cóctel de gambas, por ejemplo. ', 'También se conoce como salsa cóctel porque es la típica salsita que lleva un cóctel de gambas, por ejemplo. ', 'SARA', 'LEIVA', 'LEIVA: 
*La respuesta "salsa de tomate" sería correcta.

*También puede llevar un chorrito de salsa tabasco, salsa inglesa / Worcestershire,  mostaza, salsa Perrins y zumo de naranja, pero ninguna de estas salsas son la base. ', 'LEIVA: 
*La respuesta "salsa de tomate" sería correcta.

*También puede llevar un chorrito de salsa tabasco, salsa inglesa / Worcestershire,  mostaza, salsa Perrins y zumo de naranja, pero ninguna de estas salsas son la base. ', 'verificada', '_1LS', NOW(), 0);
