INSERT INTO preguntas (tematica, subtema, pregunta, respuesta, datos_extra, fuentes, autor, verificacion, notas_verificacion, notas_direccion, estado, nivel, fecha_creacion, version) VALUES ('DEPORTE', 'JUEGOS OLÍMPICOS', 'El lema en latín de los Juegos Olímpicos "Citius, Altius, Fortius" se traduce en español como "Más rápido, más alto"... ¿Y qué más?', '"Más fuerte"', 'El lema oficial que Pierre de Coubertin instauró, fue ampliado en 2021 a "Citius, Altius, Fortius - Communiter". Que significa "Más rápido, más alto, más fuerte - Juntos".', 'El lema oficial que Pierre de Coubertin instauró, fue ampliado en 2021 a "Citius, Altius, Fortius - Communiter". Que significa "Más rápido, más alto, más fuerte - Juntos".', 'MIGUEL ÁNGEL', 'LUIS', NULL, NULL, 'borrador', '_1LS', NOW(), 0);
